  const tzm = t.match(/\b(ist|gmt|utc|bst|cet|cest|est|edt|et|cst|pst|pdt|pt|gst|pkt|sgt|hkt|jst|aest|aedt)\b/); if (tzm) tz = tzm[1].toUpperCase();
