    if (tm){ hh = +tm[1]; mm = tm[2] && !/am|pm/.test(tm[2]) ? +tm[2] : 0; const ap = (tm[3]||(/am|pm/.test(tm[2]||"")?tm[2]:"")); if (ap==="pm" && hh<12) hh+=12; if (ap==="am" && hh===12) hh=0; }
